import dev.ocarina.NativeBridge;import java.nio.file.*;
public class BridgeEntrances{public static void main(String[]a)throws Exception{NativeBridge.load(Path.of(a[0]));long h=NativeBridge.create(Files.readAllBytes(Path.of(a[1])));int events=0;try{for(int spawn=0;spawn<13;spawn++){float[] s=NativeBridge.scene(h,85,-1,spawn,true);NativeBridge.spawn(h);double angle=s[3]*Math.PI/32768;for(int i=0;i<70;i++){NativeBridge.step(h,0,1,(float)-Math.sin(angle),(float)-Math.cos(angle),0);int[] e=NativeBridge.exitEvent(h);if(e!=null){System.out.println("spawn="+spawn+" event="+java.util.Arrays.toString(e));if(e[0]==1&&e[2]>=0)events++;break;}}}if(events<4)throw new AssertionError("Too few original doorway exit events: "+events);System.out.println("PASS walked into "+events+" ROM exits in Kokiri Forest");}finally{NativeBridge.destroy(h);}}}
